PowerShellPython <pre><code>Invoke-RestMethod -Uri "http://localhost:8080/v1/rerank" -Method Post -Body '{"query":"What is AI?","documents":["AI is artificial intelligence","Dogs are animals","Python is a language"]}' -ContentType "application/json"
</code></pre> <pre><code>import requests

response = requests.post(
    "http://localhost:8080/v1/rerank",
    json={
        "query": "What is AI?",
        "documents": [
            "AI is artificial intelligence",
            "Dogs are animals",
            "Python is a language"
        ]
    }
)
for result in response.json()["results"]:
    print(f"Index: {result['index']}, Score: {result['relevance_score']:.4f}")
</code></pre>
